import os
paths=[]
for root,ds,fs in os.walk('/home/ubuntu/continual-arc-baselines/.workbench'):
 for f in fs:
  if 'harness_state' in f: paths.append(os.path.join(root,f))
print(paths[:20],len(paths))

import json
matches=[]
for p in paths:
 try:
  d=json.load(open(p))
  txt=json.dumps(d)
  if 'c8ad7308' in txt: matches.append((p,txt[txt.index('c8ad7308')-250:txt.index('c8ad7308')+1500]))
 except Exception as e: pass
